14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    let mut current_cmd = &*cmd;
36	    if cmd.is_multicall_set() {
37	        // A multicall executable dispatches on the file name of argv0 (the
38	        // "applet"), matching clap's own parser behavior. When argv0 is the
39	        // multicall launcher itself (e.g. `busybox`, itself a registered
40	        // subcommand) the following argument selects the applet; an
41	        // unrecognized invocation name yields no candidates rather than
42	        // falling back to the root command.
43	        let applet = raw_args
44	            .next_os(&mut cursor)
45	            .and_then(|argv0| std::path::Path::new(argv0).file_stem().map(OsStr::to_owned));
46	        if let Some(applet) = applet.as_deref().and_then(OsStr::to_str) {
47	            if let Some(subcmd) = cmd.find_subcommand(applet) {
48	                debug!("complete: multicall applet={applet:?}");
49	                current_cmd = subcmd;
50	            } else {
51	                debug!("complete: unrecognized multicall applet={applet:?}");
52	                return Ok(Vec::new());
53	            }
54	        } else {
55	            debug!("complete: multicall without an applet name");
56	            return Ok(Vec::new());
57	        }
58	    } else if !cmd.is_no_binary_name_set() {
59	        raw_args.next_os(&mut cursor);
60	    }
61	    let mut pos_index = 1;
62	    let mut is_escaped = false;
63	    let mut next_state = ParseState::ValueDone;
64	    while let Some(arg) = raw_args.next(&mut cursor) {
65	        let current_state = next_state;
66	        next_state = ParseState::ValueDone;
67	        debug!(
68	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
69	            arg.to_value_os(),
70	        );
71	        if cursor == target_cursor {
72	            return complete_arg(
73	                &arg,
74	                current_cmd,
75	                current_dir,
76	                pos_index,
77	                is_escaped,
78	                current_state,
79	            );
80	        }
81	
82	        if let Ok(value) = arg.to_value() {
83	            if let Some(next_cmd) = current_cmd.find_subcommand(value) {
84	                current_cmd = next_cmd;
85	                pos_index = 1;
86	                continue;
87	            }
88	        }
89	
90	        if is_escaped {
91	            (next_state, pos_index) =
92	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
93	        } else if arg.is_escape() {
94	            is_escaped = true;
95	        } else if opt_allows_hyphen(&current_state, &arg) {
96	            match current_state {
97	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
98	                _ => unreachable!("else branch is only reachable in Opt state"),
99	            }
100	        } else if let Some((flag, value)) = arg.to_long() {
101	            if let Ok(flag) = flag {
102	                let opt = current_cmd.get_arguments().find(|a| {
103	                    let longs = a.get_long_and_visible_aliases();
104	                    let is_find = longs.map(|v| {
105	                        let mut iter = v.into_iter();
106	                        let s = iter.find(|s| *s == flag);
107	                        s.is_some()
108	                    });
109	                    is_find.unwrap_or(false)
110	                });
111	
112	                if let Some(opt) = opt {
113	                    if opt.get_num_args().expect("built").takes_values() && value.is_none() {
114	                        next_state = ParseState::Opt((opt, 1));
115	                    };
116	                } else if pos_allows_hyphen(current_cmd, pos_index) {
117	                    (next_state, pos_index) =
118	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
119	                } else {
120	                    debug!("complete: unknown flag={flag:?}");
121	                    return Ok(Vec::new());
122	                }
123	            }
124	        } else if let Some(short) = arg.to_short() {
125	            let (_, takes_value_opt, mut short) = parse_shortflags(current_cmd, short);
126	            if let Some(opt) = takes_value_opt {
127	                if short.next_value_os().is_none() {
128	                    next_state = ParseState::Opt((opt, 1));
129	                }
130	            } else if pos_allows_hyphen(current_cmd, pos_index) {
131	                (next_state, pos_index) =
132	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
133	            }
134	        } else {
135	            match current_state {
136	                ParseState::ValueDone | ParseState::Pos(..) => {
137	                    if current_cmd
138	                        .get_positionals()
139	                        .all(|p| p.get_index() != Some(pos_index))
140	                    {
141	                        debug!("complete: unrecognized argument={:?}", arg.to_value_os());
142	                        return Ok(Vec::new());
143	                    }
144	                    (next_state, pos_index) =
145	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
146	                }
147	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
148	            }
149	        }
150	    }
151	
152	    Err(std::io::Error::other("no completion generated"))
153	}
154	
155	#[derive(Debug, PartialEq, Eq, Clone)]
156	enum ParseState<'a> {
157	    /// Parsing a value done, there is no state to record.
158	    ValueDone,
159	
160	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
161	    Pos((usize, usize)),
162	
163	    /// Parsing a optional flag argument
164	    Opt((&'a clap::Arg, usize)),
165	}
166	
167	fn complete_arg(
168	    arg: &clap_lex::ParsedArg<'_>,
169	    cmd: &clap::Command,
170	    current_dir: Option<&std::path::Path>,
171	    pos_index: usize,
172	    is_escaped: bool,
173	    state: ParseState<'_>,
174	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
175	    debug!(
176	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
177	        arg,
178	        cmd.get_name(),
179	        current_dir,
180	        pos_index,
181	        state
182	    );
183	    let mut completions = Vec::<CompletionCandidate>::new();
184	
185	    match state {
186	        ParseState::ValueDone => {
187	            // After `--`, subcommands are no longer recognized; every token is
188	            // parsed as a positional value.
189	            if !is_escaped {
190	                if let Ok(value) = arg.to_value() {
191	                    completions.extend(complete_subcommand(value, cmd));
192	                }
193	            }
194	
195	            if let Some(positional) = cmd
196	                .get_positionals()
197	                .find(|p| p.get_index() == Some(pos_index))
198	            {
199	                completions.extend(complete_arg_value(
200	                    arg.to_value(),
201	                    positional,
202	                    current_dir,
203	                    0,
204	                ));
205	            }
206	            if !is_escaped {
207	                completions.extend(complete_option(arg, cmd, current_dir));
208	            }
209	        }
210	        ParseState::Pos((_, num_arg)) => {
211	            if let Some(positional) = cmd
212	                .get_positionals()
213	                .find(|p| p.get_index() == Some(pos_index))
214	            {
215	                completions.extend(complete_arg_value(
216	                    arg.to_value(),
217	                    positional,
218	                    current_dir,
219	                    num_arg.saturating_sub(1),
220	                ));
221	                if !is_escaped
222	                    && positional
223	                        .get_num_args()
224	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
225	                {
226	                    completions.extend(complete_option(arg, cmd, current_dir));
227	                }
228	            }
229	        }
230	        ParseState::Opt((opt, count)) => {
231	            completions.extend(complete_arg_value(
232	                arg.to_value(),
233	                opt,
234	                current_dir,
235	                count.saturating_sub(1),
236	            ));
237	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
238	            if count > min {
239	                // Also complete this raw_arg as a positional argument, flags, options and subcommand.
240	                completions.extend(complete_arg(
241	                    arg,
242	                    cmd,
243	                    current_dir,
244	                    pos_index,
245	                    is_escaped,
246	                    ParseState::ValueDone,
247	                )?);
248	            }
249	        }
250	    }
251	    if completions.iter().any(|a| !a.is_hide_set()) {
252	        completions.retain(|a| !a.is_hide_set());
253	    }
254	    let mut seen_ids = std::collections::HashSet::new();
255	    let mut seen_values = std::collections::HashSet::new();
256	    completions.retain(move |a| {
257	        if let Some(id) = a.get_id().cloned() {
258	            seen_ids.insert(id)
259	        } else {
260	            // Candidates without an id are deduplicated by value, keeping the
261	            // first occurrence
262	            seen_values.insert(a.get_value().to_owned())
263	        }
264	    });
265	
266	    let mut tags = Vec::new();
267	    for candidate in &completions {
268	        let tag = candidate.get_tag().cloned();
269	        if !tags.contains(&tag) {
270	            tags.push(tag);
271	        }
272	    }
273	    completions.sort_by_key(|c| {
274	        (
275	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
276	            c.get_display_order(),
277	        )
278	    });
279	
280	    Ok(completions)
281	}
282	
283	fn complete_option(
284	    arg: &clap_lex::ParsedArg<'_>,
285	    cmd: &clap::Command,
286	    current_dir: Option<&std::path::Path>,
287	) -> Vec<CompletionCandidate> {
288	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
289	    let mut completions = Vec::<CompletionCandidate>::new();
290	    if arg.is_empty() {
291	        completions.extend(longs_and_visible_aliases(cmd));
292	        completions.extend(hidden_longs_aliases(cmd));
293	
294	        let dash_or_arg = if arg.is_empty() {
295	            "-".into()
296	        } else {
297	            arg.to_value_os().to_string_lossy()
298	        };
299	        completions.extend(
300	            shorts_and_visible_aliases(cmd)
301	                .into_iter()
302	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
303	        );
304	    } else if arg.is_stdio() {
305	        // HACK: Assuming knowledge of is_stdio
306	        let dash_or_arg = if arg.is_empty() {
307	            "-".into()
308	        } else {
309	            arg.to_value_os().to_string_lossy()
310	        };
311	        completions.extend(
312	            shorts_and_visible_aliases(cmd)
313	                .into_iter()
314	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
315	        );
316	
317	        completions.extend(longs_and_visible_aliases(cmd));
318	        completions.extend(hidden_longs_aliases(cmd));
319	    } else if arg.is_escape() {
320	        // HACK: Assuming knowledge of is_escape
321	        completions.extend(longs_and_visible_aliases(cmd));
322	        completions.extend(hidden_longs_aliases(cmd));
323	    } else if let Some((flag, value)) = arg.to_long() {
324	        if let Ok(flag) = flag {
325	            if let Some(value) = value {
326	                if let Some(arg) = cmd.get_arguments().find(|a| a.get_long() == Some(flag)) {
327	                    completions.extend(
328	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
329	                            .into_iter()
330	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
331	                    );
332	                }
333	            } else {
334	                completions.extend(
335	                    longs_and_visible_aliases(cmd)
336	                        .into_iter()
337	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
338	                );
339	                completions.extend(
340	                    hidden_longs_aliases(cmd)
341	                        .into_iter()
342	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
343	                );
344	            }
345	        }
346	    } else if let Some(short) = arg.to_short() {
347	        if !short.is_negative_number() {
348	            // Find the first takes_values option.
349	            let (leading_flags, takes_value_opt, mut short) = parse_shortflags(cmd, short);
350	
351	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
352	            if let Some(opt) = takes_value_opt {
353	                let mut peek_short = short.clone();
354	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
355	                    short.next_flag();
356	                    true
357	                } else {
358	                    false
359	                };
360	
361	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
362	                completions.extend(
363	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
364	                        .into_iter()
365	                        .map(|comp| {
366	                            let sep = if has_equal { "=" } else { "" };
367	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
368	                        }),
369	                );
370	            } else {
371	                completions.extend(
372	                    shorts_and_visible_aliases(cmd)
373	                        .into_iter()
374	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
375	                );
376	            }
377	        }
378	    }
379	    debug!("complete_option: completions={completions:?}");
380	    completions
381	}
382	
383	fn complete_arg_value(
384	    value: Result<&str, &OsStr>,
385	    arg: &clap::Arg,
386	    current_dir: Option<&std::path::Path>,
387	    arg_index: usize,
388	) -> Vec<CompletionCandidate> {
389	    let mut values = Vec::new();
390	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
391	
392	    let (prefix, value) =
393	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
394	
395	    let value_os = match value {
396	        Ok(value) => OsStr::new(value),
397	        Err(value_os) => value_os,
398	    };
399	
400	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
401	        values.extend(completer.complete_at(arg_index, value_os));
402	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
403	        values.extend(complete_value_candidates(
404	            value_os,
405	            completer.value_candidates(),
406	        ));
407	    } else if let Some(possible_values) = possible_values(arg) {
408	        if let Ok(value) = value {
409	            values.extend(complete_candidates_str(
410	                value,
411	                possible_value_candidates(possible_values),
412	            ));
413	        }
414	    } else {
415	        match arg.get_value_hint() {
416	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
417	                // Should not complete
418	            }
419	            clap::ValueHint::AnyPath => {
420	                values.extend(complete_path(value_os, current_dir, &|_| true));
421	            }
422	            clap::ValueHint::FilePath => {
423	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
424	            }
425	            clap::ValueHint::DirPath => {
426	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
427	            }
428	            clap::ValueHint::ExecutablePath => {
429	                use is_executable::IsExecutable;
430	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
431	            }
432	            clap::ValueHint::CommandName
433	            | clap::ValueHint::CommandString
434	            | clap::ValueHint::CommandWithArguments
435	            | clap::ValueHint::Username
436	            | clap::ValueHint::Hostname
437	            | clap::ValueHint::Url
438	            | clap::ValueHint::EmailAddress => {
439	                // No completion implementation
440	            }
441	            _ => {
442	                // Safe-ish fallback
443	                values.extend(complete_path(value_os, current_dir, &|_| true));
444	            }
445	        }
446	
447	        values.sort();
448	    }
449	
450	    if let Some(prefix) = prefix {
451	        values = values
452	            .into_iter()
453	            .map(|comp| comp.add_prefix(prefix))
454	            .collect();
455	    }
456	    values = values
457	        .into_iter()
458	        .map(|comp| {
459	            if comp.get_tag().is_some() {
460	                comp
461	            } else {
462	                comp.tag(Some(arg.to_string().into()))
463	            }
464	        })
465	        .collect();
466	
467	    debug!("complete_arg_value: values={values:?}");
468	    values
469	}
470	
471	fn rsplit_delimiter<'s, 'o>(
472	    value: Result<&'s str, &'o OsStr>,
473	    delimiter: Option<char>,
474	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
475	    let delimiter = delimiter?;
476	    let value = value.ok()?;
477	    let pos = value.rfind(delimiter)?;
478	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
479	    Some((Some(prefix), Ok(value)))
480	}
481	
482	fn complete_value_candidates(
483	    value: &OsStr,
484	    completer: &dyn ValueCandidates,
485	) -> Vec<CompletionCandidate> {
486	    debug!("complete_value_candidates: value={value:?}");
487	
488	    let mut values = completer.candidates();
489	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
490	    values
491	}
492	
493	fn complete_candidates_str(
494	    value: &str,
495	    mut values: Vec<CompletionCandidate>,
496	) -> Vec<CompletionCandidate> {
497	    debug!("complete_candidates_str: value={value:?}");
498	
499	    values.retain(|comp| comp.get_value().starts_with(value));
500	    values
501	}
502	
503	fn complete_value_candidates_str(
504	    value: &str,
505	    completer: &dyn ValueCandidates,
506	) -> Vec<CompletionCandidate> {
507	    debug!("complete_value_candidates_str: value={value:?}");
508	
509	    complete_candidates_str(value, completer.candidates())
510	}
511	
512	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
513	    debug!(
514	        "complete_subcommand: cmd={:?}, value={:?}",
515	        cmd.get_name(),
516	        value
517	    );
518	
519	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
520	        .into_iter()
521	        .filter(|x| x.get_value().starts_with(value))
522	        .collect();
523	    if cmd.is_allow_external_subcommands_set() {
524	        let external_completer = cmd.get::<SubcommandCandidates>();
525	        if let Some(completer) = external_completer {
526	            scs.extend(complete_value_candidates_str(
527	                value,
528	                completer.value_candidates(),
529	            ));
530	        }
531	    }
532	
533	    scs.sort();
534	    scs.dedup();
535	    scs
536	}
