use clap::{Arg, ArgAction, Command};

fn build() -> Command {
    Command::new("tool")
        .arg(
            Arg::new("color")
                .long("color")
                .action(ArgAction::Append)
                .num_args(0..=1)
                .value_parser(["auto", "always", "never"]),
        )
        .arg(
            Arg::new("format")
                .long("format")
                .value_parser(["json", "yaml"]),
        )
        .arg(
            Arg::new("files")
                .action(ArgAction::Append)
                .value_parser(["a.txt", "b.txt"]),
        )
}

fn show(args: &[&str]) {
    let mut full = vec!["tool"];
    full.extend_from_slice(args);
    match build().try_get_matches_from(full) {
        Ok(m) => {
            let color: Vec<_> = m
                .get_many::<String>("color")
                .map(|v| v.map(|s| s.as_str()).collect())
                .unwrap_or_default();
            let format = m.get_one::<String>("format").map(|s| s.as_str());
            let files: Vec<_> = m
                .get_many::<String>("files")
                .map(|v| v.map(|s| s.as_str()).collect())
                .unwrap_or_default();
            let occ = m.indices_of("color").map(|i| i.collect::<Vec<_>>());
            println!("OK   {args:?}: color={color:?} (indices {occ:?}), format={format:?}, files={files:?}");
        }
        Err(e) => println!("ERR  {args:?}: {:?} - {}", e.kind(), e.to_string().lines().next().unwrap_or("")),
    }
}

fn main() {
    show(&["--color"]);
    show(&["--color", "--format", "json"]);
    show(&["--color=auto", "--format", "json"]);
    show(&["--color", "auto", "--color", "never"]);
    show(&["--color="]);
    show(&["--color=", "--format", "js"]);
    show(&["--color", "a.txt"]);
    show(&["--color", "xx"]);
    show(&["--color=xx"]);
    show(&["--format", "json", "--format", "yaml"]);
    show(&["--format", "--color"]);
    show(&["a.txt", "b.txt", "a.txt"]);
    show(&["--color", "always", "--color", "--format", "json"]);
    show(&["--format", "json"]);
    show(&["--color", "always", "--color"]);
}

