                debug!("Parser::react: cur_idx:={}", self.cur_idx.get());
            }
            self.start_custom_arg(matcher, arg, source);
            ok!(self.push_arg_values(arg, raw_vals, source, matcher));
            if cfg!(debug_assertions) && matcher.needs_more_vals(arg) {
